DO $$
DECLARE
  v_book_id INTEGER;
  v_edit_id INTEGER;
  v_editorial_name TEXT := 'Austral';
  v_title TEXT := 'Filipicas';
  v_summary TEXT := 'Conjunto de catorce discursos pronunciados por Marco Tulio Cicerón contra Marco Antonio en el Senado y ante la Asamblea de los Ciudadanos a partir del 2 de septiembre del año 44 a.C. y hasta mediados del año 43. En ellos Cicerón critica las actuaciones de Marco Antonio, que se perfilaba como sucesor de Julio César tras su asesinato, y logra que el Senado termine poniéndose en contra de aquél, quien finalmente es derrotado en Módena y declarado enemigo de Roma. El título, "Filípicas", se debe a la admiración que Cicerón sentía por Demóstenes y los discursos que este autor escribió contra Filipo II de Macedonia. Marcan el apogeo de la elocuencia ciceroniana y constituyen un auténtico paradigma de la norma clásica.';
BEGIN
  INSERT INTO wm_books (title, summary, genre_id)
  VALUES (v_title, v_summary, (SELECT id_genre FROM wm_genres WHERE name = 'Ensayo'))
