DO $$
DECLARE
  v_book_id INTEGER;
  v_edit_id INTEGER;
  v_editorial_name TEXT := 'Servicios Editoriales';
  v_title TEXT := 'La teoria de la relatividad';
  v_summary TEXT := 'Exposición divulgativa de la teoría de la relatividad, formulada por el físico alemán Albert Einstein (1879-1955), una de las mayores revoluciones científicas del siglo XX. A través de un lenguaje accesible, el libro explica los postulados de la relatividad especial y general, conceptos como la dilatación del tiempo, la contracción de la longitud, la equivalencia entre masa y energía (E=mc²) y la curvatura del espacio-tiempo. Una obra que permite al lector no especializado comprender las ideas que cambiaron nuestra visión del universo, abriendo paso a la física moderna, la cosmología y la era atómica.';
BEGIN
  INSERT INTO wm_books (title, summary, genre_id)
